//nos va a traer el mensaje de en los time stamps dados icluyendo el time stamp de inicio a fin

//XRANGE fruits 17955484396-0 +
XRANGE fruits - (1795548439698-0

//para borrar el stream creado
DEL fruits 

//para crear un stream y asignarle un grupo al stream
XGROUP CREATE fruits fruits-group $ MkSTREAM

//Crea un nuevo consumidor
XGROUP CREATECONSUMER fruits fruits-group worker-1 
XGROUP CREATECONSUMER fruits fruits-group worker-2 

// Nunca especificar una ID, dejar que redis lo haga automaticamente.
XADD fruits 10-0 name banana color yellow 
XADD fruits 20-0 name apple color red 
XADD fruits 30-0 name orange color orange
